//! 🧪️ Genuine typed-field nulls and comparisons preserve original source custody and one finite bank.
use super::*;
use semio_framework_value_clone_source::RetainedCloneSource;
use semio_framework_value_testing_allocator::{observe_retirement_allocations as observe,refuse_one_allocation_on_this_thread as refuse};
type Pair=(String,String);
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn debit(bank:&mut RetainedCloneGrant,remaining_work:&mut u64,quoted:u64,work:u128,p:RetainedCloneProgress,heap:(usize,usize),totals:&mut(usize,usize)){assert!(work<=u128::from(quoted)&&work<=u128::from(*remaining_work));assert!(p.fits(*bank));assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));*remaining_work-=u64::try_from(work).unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;totals.0+=heap.0;totals.1+=heap.1;}
fn source(value:Pair,bank:&mut RetainedCloneGrant,remaining_work:&mut u64,totals:&mut(usize,usize))->RetainedCloneSource<Pair>{
 let mut admission=RetainedCloneSource::<Pair>::admission_owned(value,());let mut output=None;
 for _ in 0..64{
  let ready=admission.phase()=="ready";let d=if ready{RetirementDemand{depth:1,..Default::default()}}else{admission.next_demand().unwrap()};let quoted=if ready{1}else{admission.advance_work_demand().unwrap()};let g=grant(d);
  assert!(g.maximum_items<=bank.maximum_items&&g.maximum_copy_bytes<=bank.maximum_copy_bytes&&g.maximum_capacity_bytes<=bank.maximum_capacity_bytes&&g.maximum_release_bytes<=bank.maximum_release_bytes&&g.maximum_depth<=bank.maximum_depth);
  let mut actual=None;let(turn,h)=observe(||if ready{admission.take_output(&mut output,g)}else{crate::eff::with_effect(g,quoted,&mut actual,|effect|admission.advance(effect))});let work=turn.work;let progress=turn.result.unwrap().progress();if let Some(bytes)=actual{assert_eq!(bytes,progress.retained_capacity_bytes);}debit(bank,remaining_work,quoted,work,progress,h,totals);
  if output.is_some(){break}
 }
 assert!(admission.terminal_is_empty());output.unwrap()
}
fn close(source:&mut RetainedCloneSource<Pair>,bank:&mut RetainedCloneGrant,remaining_work:&mut u64,totals:&mut(usize,usize),limit:u64){for _ in 0..limit{if source.terminal_is_empty(){break}let quoted=source.next_close_work_demand(4096).unwrap();let g=grant(source.next_close_demand(4096).unwrap());let(turn,h)=observe(||crate::eff::settled(crate::eff::with_effect(g,quoted,&mut None,|effect|source.close_step(effect))));let work=turn.work;debit(bank,remaining_work,quoted,work,turn.result.unwrap().progress(),h,totals);}assert!(source.terminal_is_empty());}
#[test]
fn typed_record_actual_null_retry_comparison_and_close_preserve_original_bank(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("actual.schema.json")).unwrap();assert_eq!(schema["properties"]["laws"]["const"],law["laws"]);let limit=law["maximumTurns"].as_u64().unwrap();
 for row in law["cases"].as_array().unwrap(){
  let stock=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let mut remaining_work=law["workUnits"].as_u64().unwrap();
  let((left,right),mut totals)=observe(||(serde_json::from_value::<Pair>(row["left"].clone()).unwrap(),serde_json::from_value::<Pair>(row["right"].clone()).unwrap()));let mut left=source(left,&mut bank,&mut remaining_work,&mut totals);let mut right=source(right,&mut bank,&mut remaining_work,&mut totals);let pointers=(left.borrow().get().0.as_ptr(),right.borrow().get().0.as_ptr());let mut owner=RetainedEqualityOwner::<Pair>::new();
  for _ in 0..limit{let maximum=remaining_work.min(4096);let quoted=owner.work_demand(4096,maximum).unwrap();let d=owner.demand(4096,maximum).unwrap();if d.capacity_bytes>0{break}let g=grant(d);let mut actual=None;let(turn,h)=observe(||crate::eff::adv_owner(&mut owner,left.borrow(),right.borrow(),4096,maximum,g,&mut actual));let work=turn.work;let step=turn.result.unwrap();assert!(step.equal.is_none());assert!(actual.is_none());debit(&mut bank,&mut remaining_work,quoted,work,step.progress,h,&mut totals);}
  let maximum=remaining_work.min(4096);let quoted=owner.work_demand(4096,maximum).unwrap();let d=owner.demand(4096,maximum).unwrap();assert!(d.capacity_bytes>0);let g=grant(d);let mut actual=None;let(turn,h)=observe(||crate::eff::adv_owner(&mut owner,left.borrow(),right.borrow(),4096,maximum,RetainedCloneGrant{maximum_items:0,..g},&mut actual));assert!(actual.is_none());assert_eq!(turn.work,u128::from(law["deniedWork"].as_u64().unwrap()));assert!(turn.result.unwrap().equal.is_none());assert_eq!(h,(0,0));let((turn,attempts),h)=observe(||refuse(||crate::eff::adv_owner(&mut owner,left.borrow(),right.borrow(),4096,maximum,g,&mut actual)));assert_eq!(attempts,1);assert_eq!(actual,Some(0));assert!(turn.work<=u128::from(quoted));let work=turn.work;let error=turn.result.err().unwrap();debit(&mut bank,&mut remaining_work,quoted,work,error.retained_progress(),h,&mut totals);assert_eq!(owner.result(),None);assert_eq!(left.borrow().get().0.as_ptr(),pointers.0);assert_eq!(right.borrow().get().0.as_ptr(),pointers.1);
  for _ in 0..limit{if owner.result().is_some(){break}let maximum=remaining_work.min(4096);let quoted=owner.work_demand(4096,maximum).unwrap();let g=grant(owner.demand(4096,maximum).unwrap());let mut actual=None;let(turn,h)=observe(||crate::eff::adv_owner(&mut owner,left.borrow(),right.borrow(),4096,maximum,g,&mut actual));let work=turn.work;if let Some(bytes)=actual{assert_eq!(bytes,turn.result.as_ref().unwrap().progress.retained_capacity_bytes)}debit(&mut bank,&mut remaining_work,quoted,work,turn.result.unwrap().progress,h,&mut totals);}assert_eq!(owner.result(),Some(row["left"]==row["right"]));let mut actual=None;let(turn,h)=observe(||crate::eff::adv_owner(&mut owner,left.borrow(),right.borrow(),4096,0,Default::default(),&mut actual));assert!(actual.is_none());assert_eq!(turn.work,u128::from(law["cachedWork"].as_u64().unwrap()));assert_eq!(turn.result.unwrap().progress,Default::default());assert_eq!(h,(0,0));
  owner.begin_close();for _ in 0..limit{if owner.terminal_is_empty(){break}let quoted=owner.close_work_demand(4096).unwrap();let g=grant(owner.close_demand(4096).unwrap());let(turn,h)=observe(||crate::eff::close_owner(&mut owner,g));let work=turn.work;debit(&mut bank,&mut remaining_work,quoted,work,turn.result.unwrap().progress(),h,&mut totals);}assert!(owner.terminal_is_empty());assert_eq!(observe(||drop(owner)).1,(0,0));close(&mut left,&mut bank,&mut remaining_work,&mut totals,limit);close(&mut right,&mut bank,&mut remaining_work,&mut totals,limit);assert_eq!(observe(||drop((left,right))).1,(0,0));assert_eq!(totals.0,totals.1);
 }
}

#[test]
fn compound_zero_sized_equality_cannot_collapse_a_large_input_into_one_paid_probe(){
 let law:serde_json::Value=serde_json::from_str(include_str!("actual.json")).unwrap();assert_eq!(law["compoundTraversal"]["zeroArrayLength"],4097);type Value=Option<[();4097]>;let left=Some([();4097]);let right=Some([();4097]);assert_eq!(left,right);let mut cursor=Value::equality_cursor();let stock=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:stock["release"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize};let mut remaining_work=law["workUnits"].as_u64().unwrap();let mut totals=(0,0);
 while bank.maximum_items>law["compoundTraversal"]["reserveCloseItems"].as_u64().unwrap()as usize&&remaining_work>law["compoundTraversal"]["reserveCloseWork"].as_u64().unwrap(){let maximum=(remaining_work-law["compoundTraversal"]["reserveCloseWork"].as_u64().unwrap()).min(64);let quoted=RetainedEqualityCursor::<Option<[();4097]>>::work_demand(&cursor,4096,maximum).unwrap();if quoted==0{break}let g=grant(RetainedEqualityCursor::<Option<[();4097]>>::demand(&cursor,4096,maximum).unwrap());let mut actual=None;let(turn,h)=observe(||crate::eff::adv_cursor(&mut cursor,&left,&right,4096,maximum,g,&mut actual));if let Some(bytes)=actual{assert_eq!(bytes,turn.result.as_ref().unwrap().progress.retained_capacity_bytes)}let work=turn.work;let step=turn.result.unwrap();assert!(step.equal.is_none());debit(&mut bank,&mut remaining_work,quoted,work,step.progress,h,&mut totals);}
 let d=RetainedEqualityCursor::<Option<[();4097]>>::demand(&cursor,4096,64).unwrap();let mut actual=None;let(turn,h)=observe(||crate::eff::adv_cursor(&mut cursor,&left,&right,4096,64,RetainedCloneGrant{maximum_items:0,..grant(d)},&mut actual));assert!(actual.is_none());assert_eq!(turn.work,0);let step=turn.result.unwrap();assert!(step.equal.is_none());assert_eq!(step.progress,Default::default());assert_eq!(h,(0,0));cursor.begin_close();while !cursor.terminal_is_empty(){let quoted=cursor.close_work_demand(4096).unwrap();let g=grant(cursor.close_demand(4096).unwrap());let(turn,h)=observe(||crate::eff::close_cursor::<Option<[();4097]>,_>(&mut cursor,g));let work=turn.work;debit(&mut bank,&mut remaining_work,quoted,work,turn.result.unwrap().progress(),h,&mut totals);}assert_eq!(observe(||drop(cursor)).1,(0,0));assert_eq!(totals.0,totals.1);
}

#[test]
fn string_cursor_stages_source_headers_under_the_neutral_admission_vectors(){
 let rows:serde_json::Value=serde_json::from_str(include_str!("../../../📋️list/🟰️equal/🧪️tests/🧫️fixtures/🔎️inspection.json")).unwrap();
 for row in rows.as_array().unwrap(){
  let left=String::from("left");let right=String::from("right");let mut c=String::equality_cursor();let work=row["work"].as_u64().unwrap()+2;let d=c.demand(4096,work).unwrap();let mut g=grant(d);if !row["physical"].as_bool().unwrap(){g.maximum_copy_bytes=0;}
  let selected=c.work_demand(4096,work).unwrap();let mut actual=None;let(turn,heap)=observe(||crate::eff::adv_cursor(&mut c,&left,&right,4096,work,g,&mut actual));assert!(actual.is_none());assert_eq!(heap,(0,0));let expected=row["inspected"].as_bool().unwrap();assert_eq!(turn.work,if expected{5}else{0});assert!(turn.work<=u128::from(selected));assert!(turn.result.unwrap().progress.fits(g));c.begin_close();
  while !c.terminal_is_empty(){let g=grant(c.close_demand(4096).unwrap());let quoted=c.close_work_demand(4096).unwrap();let(turn,heap)=observe(||crate::eff::close_cursor(&mut c,g));assert_eq!(heap,(0,0));assert!(turn.work<=u128::from(quoted));assert!(turn.result.unwrap().progress().fits(g));}
 }
}

std::thread_local!{static FIELD_BIRTHS:std::cell::Cell<usize>=const{std::cell::Cell::new(0)};}
struct TestEqualityBirth;
impl RetainedEqualityBirth for TestEqualityBirth{type Output=u64;fn work()->Result<u64,ValueError>{Ok(1)}fn birth()->u64{FIELD_BIRTHS.with(|n|n.set(n.get()+1));7}}
#[test]
fn equality_cursor_birth_reports_real_allocation_and_never_constructs_on_refusal(){
 let rows:serde_json::Value=serde_json::from_str(include_str!("birth.json")).unwrap();
 for row in rows.as_array().unwrap(){let d=RetirementDemand{copy_bytes:size_of::<u64>()*2,capacity_bytes:size_of::<u64>(),depth:1,..Default::default()};let mut g=grant(d);if !row["admitted"].as_bool().unwrap(){g.maximum_items=0}let before=FIELD_BIRTHS.with(|n|n.get());let mut actual=None;
  let(turn,heap)=if row["allocationFails"].as_bool().unwrap(){let((turn,attempts),heap)=observe(||refuse(||equality_box::<TestEqualityBirth>(2+u64::try_from(size_of::<u64>()*2).unwrap(),g,&mut actual)));assert_eq!(attempts,1);(turn,heap)}else{observe(||equality_box::<TestEqualityBirth>(2+u64::try_from(size_of::<u64>()*2).unwrap(),g,&mut actual))};
  let marker=match actual{None=>"none",Some(0)=>"failed",Some(n)if n==size_of::<u64>()=>"bytes",_=>panic!("unexpected actual marker")};assert_eq!(marker,row["marker"].as_str().unwrap());assert_eq!(FIELD_BIRTHS.with(|n|n.get())>before,row["constructed"].as_bool().unwrap());
  if let Ok(Some((value,p)))=turn.result{assert_eq!(*value,7);assert_eq!(heap.0,p.retained_capacity_bytes);drop(value)}else{assert_eq!(heap,(0,0));}
 }
}
